(()=>{const K="mipasantia_maqueta_v1",note=(t,ok)=>{let e=document.querySelector("#auth-message");if(e)e.innerHTML='<p class="notice '+(ok?"ok":"error")+'>'+t+"</p>"};document.addEventListener("click",e=>{let a=e.target.closest("[data-action]");if(!a)return;let k=a.dataset.action;if(k==="close"){document.querySelector("#modal-root").innerHTML="";return}if((k==="login"||k==="register")&&a.closest("#modal-root")){let target=document.querySelector(".session [data-action="+k+"]");if(target)target.click()}});document.addEventListener("submit",e=>{let f=e.target;if(f.id!=="auth-form")return;e.preventDefault();let d=JSON.parse(localStorage.getItem(K)||"{}"),x=Object.fromEntries(new FormData(f)),login=f.dataset.kind==="login";d.users=d.users||[];if(login){let u=d.users.find(z=>z.email&&z.email.toLowerCase()===x.email.toLowerCase()&&z.password===x.password);if(!u){note("Correo o contraseña incorrectos. Usá la cuenta de demostración.",false);return}d.current=u.id}else{if(d.users.some(z=>z.email&&z.email.toLowerCase()===x.email.toLowerCase())){note("Ese correo ya fue usado en esta maqueta.",false);return}let u={id:Date.now(),nombre:x.name.trim(),email:x.email.trim(),password:x.password,curso:"Estudiante",bio:""};d.users.push(u);d.current=u.id}localStorage.setItem(K,JSON.stringify(d));document.querySelector("#modal-root").innerHTML="";location.hash="inicio";location.reload()})})();
